from collections import deque
from typing import List

class Solution:
    def maxHotelRoomHeight(self, hotel: List[List[str]]) -> int:
        if not hotel or not hotel[0]:
            return 0

        rows = len(hotel)
        cols = len(hotel[0])

        queue = deque()

        for row in range(rows):
            for col in range(cols):
                if hotel[row][col] == "E":
                    queue.append((row, col, 0))

        directions = [
            (1, 0),
            (-1, 0),
            (0, 1),
            (0, -1)
        ]

        maxHeight = 0

        while queue:
            row, col, distance = queue.popleft()
            maxHeight = max(maxHeight, distance)

            for dr, dc in directions:
                nextRow = row + dr
                nextCol = col + dc

                if nextRow < 0 or nextRow >= rows:
                    continue

                if nextCol < 0 or nextCol >= cols:
                    continue

                if hotel[nextRow][nextCol] != "-":
                    continue

                hotel[nextRow][nextCol] = str(distance + 1)
                queue.append((nextRow, nextCol, distance + 1))

        return maxHeight

