from collections import deque


def solution(greenhouse):
    if not greenhouse or not greenhouse[0]:
        return 0
    rows = len(greenhouse)
    cols = len(greenhouse[0])
    dist = [[-1] * cols for _ in range(rows)]
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if greenhouse[r][c] == "W":
                dist[r][c] = 0
                queue.append((r, c))
    best = 0
    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if greenhouse[nr][nc] == "-" and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    best = max(best, dist[nr][nc])
                    queue.append((nr, nc))
    return best

