function solution(greenhouse) {
  if (!greenhouse || greenhouse.length === 0 || greenhouse[0].length === 0) {
    return 0;
  }
  const rows = greenhouse.length;
  const cols = greenhouse[0].length;
  const dist = Array.from({ length: rows }, () => new Array(cols).fill(-1));
  const queue = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (greenhouse[r][c] === "W") {
        dist[r][c] = 0;
        queue.push([r, c]);
      }
    }
  }
  let best = 0;
  let head = 0;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  while (head < queue.length) {
    const [r, c] = queue[head++];
    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
        if (greenhouse[nr][nc] === "-" && dist[nr][nc] === -1) {
          dist[nr][nc] = dist[r][c] + 1;
          best = Math.max(best, dist[nr][nc]);
          queue.push([nr, nc]);
        }
      }
    }
  }
  return best;
}

