from typing import List

class Solution:
    def findLargestNumber(self, digits: List[int]) -> int:
        self.best = 0
        self._backtrack(digits, 0, 0, 0)
        return self.best

    def _backtrack(
        self,
        digits: List[int],
        index: int,
        currentNumber: int,
        chosenCount: int
    ) -> None:
        if 1 <= chosenCount <= 3:
            self.best = max(self.best, currentNumber)

        if chosenCount == 3:
            return

        for i in range(index, len(digits)):
            nextNumber = currentNumber * 10 + digits[i]
            self._backtrack(digits, i + 1, nextNumber, chosenCount + 1)

reference_solution.javascript:
function solution(digits) {
  const n = digits.length;
  let best = 0;
  for (const k of [1, 2, 3]) {
    if (k > n) continue;
    let value = 0;
    let start = 0;
    for (let slot = 0; slot < k; slot++) {
      const remainingAfter = k - slot - 1;
      const limit = n - remainingAfter;
      let chosenIdx = start;
      for (let i = start; i < limit; i++) {
        if (digits[i] > digits[chosenIdx]) {
          chosenIdx = i;
        }
      }
      value = value * 10 + digits[chosenIdx];
      start = chosenIdx + 1;
    }
    best = Math.max(best, value);
  }
  return best;
}

