class Solution:
    def minReductionsToPyramid(self, heights: List[int]) -> int:
        totalHeight = 0
        for height in heights:
            totalHeight += height

        allowedHeight = 0
        for i in range(len(heights)):
            allowedHeight += 1

            if heights[i] > allowedHeight:
                heights[i] = allowedHeight
            else:
                allowedHeight = heights[i]

        allowedHeight = 0
        for i in range(len(heights) - 1, -1, -1):
            allowedHeight += 1

            if heights[i] > allowedHeight:
                heights[i] = allowedHeight
            else:
                allowedHeight = heights[i]

        peakHeight = 0
        for height in heights:
            if height > peakHeight:
                peakHeight = height

        return totalHeight - peakHeight * peakHeight

