function solution(heights) {
  const n = heights.length;
  if (n === 0) return 0;
  const left = new Array(n);
  left[0] = Math.min(heights[0], 1);
  for (let i = 1; i < n; i++) left[i] = Math.min(heights[i], left[i - 1] + 1);
  const right = new Array(n);
  right[n - 1] = Math.min(heights[n - 1], 1);
  for (let i = n - 2; i >= 0; i--) right[i] = Math.min(heights[i], right[i + 1] + 1);
  let bestKept = 0;
  for (let i = 0; i < n; i++) {
    const peak = Math.min(left[i], right[i]);
    bestKept = Math.max(bestKept, peak * peak);
  }
  let total = 0;
  for (const h of heights) total += h;
  return total - bestKept;
}

