/**
 * @param {number[]} alerts
 * @param {number[]} durability
 * @param {number} power
 * @return {number}
 */
function solution(alerts, durability, power) {
  const n = alerts.length;
  const seconds = durability.map((d) => Math.ceil(d / power));

  const order = [...Array(n).keys()].sort(
    (a, b) => seconds[a] * alerts[b] - seconds[b] * alerts[a]
  );

  let total = 0;
  const remaining = new Set([...Array(n).keys()]);
  for (const i of order) {
    let rate = 0;
    for (const j of remaining) rate += alerts[j];
    total += rate * seconds[i];
    remaining.delete(i);
  }
  return total + 1;
}

