 * @param {{name: string, children: Array}} tree
 * @param {string} nameA
 * @param {string} nameB
 * @return {string|null}
 */
function solution(tree, nameA, nameB) {
  if (nameA === nameB) return nameA;
  const targets = new Set([nameA, nameB]);
  let answer = null;

  function dfs(node) {
    const found = new Set();
    if (targets.has(node.name)) found.add(node.name);
    for (const child of node.children || []) {
      for (const f of dfs(child)) found.add(f);
    }
    if (answer === null && found.size === 2) answer = node.name;
    return found;
  }

  dfs(tree);
  return answer;
}

