/**
 * @param {string[]} members
 * @return {string[]}
 */
function solution(members) {
  const used = new Set();
  const result = [];
  for (const full of members) {
    const parts = full.trim().split(/\s+/);
    const first = parts[0].toLowerCase().replace(/[^a-z]/g, "");
    const last = parts[parts.length - 1].toLowerCase().replace(/[^a-z]/g, "");
    const base = (last + first).slice(0, 8);
    let handle;
    if (!used.has(base)) {
      handle = base;
    } else {
      let n = 1;
      while (true) {
        const suffix = String(n);
        const candidate = base.slice(0, 8 - suffix.length) + suffix;
        if (!used.has(candidate)) {
          handle = candidate;
          break;
        }
        n += 1;
      }
    }
    used.add(handle);
    result.push(handle);
  }
  return result;
}

