class Solution:
    def findBusiestDesk(self, deskCapacity: List[int], activityLog: List[str]) -> int:
        n = len(deskCapacity)
        currentLoad = [0] * n
        totalProcessed = [0] * n
        closed = [False] * n
        pointer = 0

        for event in activityLog:
            if event.startswith("CLOSE"):
                index = int(event.split(" ")[1])
                closed[index] = True
            else:
                assigned = self._assignBook(n, currentLoad, deskCapacity, closed, pointer)

                if assigned == -1:
                    for i in range(n):
                        if not closed[i]:
                            currentLoad[i] = 0

                    pointer = 0
                    assigned = self._assignBook(n, currentLoad, deskCapacity, closed, pointer)

                totalProcessed[assigned] += 1
                currentLoad[assigned] += 1
                pointer = (assigned + 1) % n

        maxProcessed = 0
        result = 0

        for i in range(n):
            if totalProcessed[i] >= maxProcessed:
                maxProcessed = totalProcessed[i]
                result = i

        return result

    def _assignBook(self, n, currentLoad, deskCapacity, closed, startPointer):
        for step in range(n):
            index = (startPointer + step) % n
            if not closed[index] and currentLoad[index] < deskCapacity[index]:
                return index

        return -1

