from typing import List

def solution(printerLimit: List[int], eventLog: List[str]) -> int:
    n = len(printerLimit)
    offline = [False] * n
    load = [0] * n      # jobs since last reset
    total = [0] * n     # jobs over the whole day
    ptr = 0

    def assign():
        nonlocal ptr
        for _ in range(n):
            i = ptr % n
            if not offline[i] and load[i] < printerLimit[i]:
                load[i] += 1
                total[i] += 1
                ptr = (i + 1) % n
                return True
            ptr = (ptr + 1) % n
        return False

    for event in eventLog:
        if event == "JOB":
            if not assign():
                for j in range(n):
                    if not offline[j]:
                        load[j] = 0
                ptr = 0
                assign()
        else:
            idx = int(event.split()[1])
            offline[idx] = True

