 * @param {number[]} printerLimit
 * @param {string[]} eventLog
 * @return {number}
 */
function solution(printerLimit, eventLog) {
  const n = printerLimit.length;
  const offline = Array(n).fill(false);
  const load = Array(n).fill(0);
  const total = Array(n).fill(0);
  let ptr = 0;

  function assign() {
    for (let s = 0; s < n; s++) {
      const i = ptr % n;
      if (!offline[i] && load[i] < printerLimit[i]) {
        load[i] += 1;
        total[i] += 1;
        ptr = (i + 1) % n;
        return true;
      }
      ptr = (ptr + 1) % n;
    }
    return false;
  }

  for (const event of eventLog) {
    if (event === "JOB") {
      if (!assign()) {
        for (let j = 0; j < n; j++) if (!offline[j]) load[j] = 0;
        ptr = 0;
        assign();
      }
    } else {
      const idx = parseInt(event.split(/\s+/)[1], 10);
      offline[idx] = true;
    }
  }

  let best = -1;
  let bestIndex = -1;
  for (let i = 0; i < n; i++) {
    if (total[i] >= best) {
      best = total[i];
      bestIndex = i;
    }
  }
  return bestIndex;
}

