class Solution:
    def crawl(self, startUrl, parser):
        startHost = self._getHost(startUrl)
        visited = set()
        visitedLock = threading.Lock()

        pool = ThreadPoolExecutor(max_workers=max(4, os.cpu_count()))

        taskCount = [0]
        taskLock = threading.Lock()

        cleanStart = self._cleanUrl(startUrl)
        visited.add(cleanStart)

        self._submit(
            startUrl,
            parser,
            startHost,
            visited,
            visitedLock,
            pool,
            taskCount,
            taskLock
        )

        while True:
            with taskLock:
                if taskCount[0] == 0:
                    break
            time.sleep(0.001)

        pool.shutdown()
        return list(visited)

    def _submit(self, url, parser, host, visited, visitedLock, pool, taskCount, taskLock):
        with taskLock:
            taskCount[0] += 1

        def work():
            try:
                links = parser.getLinks(url)

                for link in links:
                    cleanLink = self._cleanUrl(link)
                    linkHost = self._getHost(cleanLink)

                    if linkHost != host:
                        continue

                    with visitedLock:
                        if cleanLink not in visited:
                            visited.add(cleanLink)
                            shouldSubmit = True
                        else:
                            shouldSubmit = False

                    if shouldSubmit:
                        self._submit(
                            link,
                            parser,
                            host,
                            visited,
                            visitedLock,
                            pool,
                            taskCount,
                            taskLock
                        )
            finally:
                with taskLock:
                    taskCount[0] -= 1

        pool.submit(work)

    def _getHost(self, url):
        start = url.find("://")
        if start == -1:
            start = 0
        else:
            start += 3

        end = url.find("/", start)
        if end == -1:
            end = len(url)

        return url[start:end]

    def _cleanUrl(self, url):
        index = url.find("#")
        if index == -1:
            return url
        return url[:index]

