def solution(start_url, link_map):
    def strip_fragment(url):
        i = url.find('#')
        return url if i == -1 else url[:i]

    def host_of(url):
        after = url.split('://', 1)[1]
        slash = after.find('/')
        return after if slash == -1 else after[:slash]

    start = strip_fragment(start_url)
    host = host_of(start)
    seen = {start}
    stack = [start]
    while stack:
        current = stack.pop()
        for raw in link_map.get(current, []):
            clean = strip_fragment(raw)
            if host_of(clean) == host and clean not in seen:
                seen.add(clean)
                stack.append(clean)
    return sorted(seen)

