    const i = url.indexOf('#');
    return i === -1 ? url : url.slice(0, i);
  };
  const hostOf = (url) => {
    const after = url.split('://')[1];
    const slash = after.indexOf('/');
    return slash === -1 ? after : after.slice(0, slash);
  };
  const start = stripFragment(startUrl);
  const host = hostOf(start);
  const seen = new Set([start]);
  const stack = [start];
  while (stack.length) {
    const current = stack.pop();
    const links = linkMap[current] || [];
    for (const raw of links) {
      const clean = stripFragment(raw);
      if (hostOf(clean) === host && !seen.has(clean)) {
        seen.add(clean);
        stack.push(clean);
      }
    }
  }
  return Array.from(seen).sort();
}

