from typing import List

class Creator:
    def __init__(self, id: int, earnings: int):
        self.id = id
        self.total = earnings

    def __eq__(self, other):
        return isinstance(other, Creator) and self.id == other.id

    def __lt__(self, other):
        if self.total != other.total:
            return self.total > other.total
        return self.id < other.id

    def __hash__(self):
        return hash(self.id)


class EarningsTracker:
    def __init__(self):
        self.nextId = 0
        self.creatorMap = {}
        self.sortedSet = SortedSet()

    def addCreator(self, earnings: int) -> int:
        cid = self.nextId
        self.nextId += 1
        creator = Creator(cid, earnings)
        self.creatorMap[cid] = creator
        self.sortedSet.add(creator)
        return cid

    def addCreatorByInvite(self, earnings: int, inviterId: int) -> int:
        inviter = self.creatorMap.get(inviterId)
        if inviter is None:
            return -1

        cid = self.nextId
        self.nextId += 1
        creator = Creator(cid, earnings)
        self.creatorMap[cid] = creator
        self.sortedSet.add(creator)

        self.sortedSet.remove(inviter)
        inviter.total += earnings
        self.sortedSet.add(inviter)

        return cid

    def getTopCreators(self, k: int, minEarnings: int) -> List[int]:
        result = []
        for creator in self.sortedSet:
            if creator.total < minEarnings:
                break
            result.append(creator.id)
            if len(result) == k:
                break
        return result

