      totals.push(earnings);
      totals[inviter] += earnings;
      results.push(memberId);
    } else if (name === 'topMembers') {
      const k = op[1];
      const minEarnings = op[2];
      const ranked = [];
      for (let i = 0; i < totals.length; i++) {
        if (totals[i] >= minEarnings) ranked.push([i, totals[i]]);
