from typing import List

class CampgroundAllocator:
    def __init__(self, spotList: List[str]):
        self.scheduleMap = {}
        for spot in spotList:
            self.scheduleMap[spot] = []

    def assign(self, arrival: int, departure: int) -> str:
        for spot in sorted(self.scheduleMap.keys()):
            bookings = self.scheduleMap[spot]

            insertPos = self.findInsertPosition(bookings, arrival, departure)

            if insertPos > 0:
                previousStay = bookings[insertPos - 1]
                if previousStay[1] > arrival:
                    continue

            if insertPos < len(bookings):
                nextStay = bookings[insertPos]
                if nextStay[0] < departure:
                    continue

            bookings.insert(insertPos, [arrival, departure])
            return spot

        return ""

    def findInsertPosition(self, bookings: List[List[int]], arrival: int, departure: int) -> int:
        low = 0
        high = len(bookings) - 1

        while low <= high:
            mid = (low + high) // 2
            current = bookings[mid]

            if current[0] >= departure:
                high = mid - 1
            elif current[1] <= arrival:
                low = mid + 1
            else:
                high = mid - 1

        return low

