from typing import Dict, List


class Expression:
    def __init__(self, value: int, text: str, operator: str):
        self.value = value
        self.text = text
        self.operator = operator


class Solution:
    def buildTargetExpression(self, numbers: List[int], target: int) -> str:
        memo = {}

        valueToExpression = self._compute(numbers, 0, len(numbers) - 1, memo)

        if target not in valueToExpression:
            return ""

        return valueToExpression[target].text + "=" + str(target)

    def _compute(
        self,
        numbers: List[int],
        start: int,
        end: int,
        memo: Dict[str, Dict[int, Expression]]
    ) -> Dict[int, Expression]:
        key = str(start) + "," + str(end)

        if key in memo:
            return memo[key]

        result = {}

        if start == end:
            value = numbers[start]
            result[value] = Expression(value, str(value), "")
            memo[key] = result
            return result

        for split in range(start, end):
            leftMap = self._compute(numbers, start, split, memo)
            rightMap = self._compute(numbers, split + 1, end, memo)

            for leftExpression in leftMap.values():
                for rightExpression in rightMap.values():
                    sumValue = leftExpression.value + rightExpression.value
                    sumText = self._formatExpression(leftExpression, rightExpression, "+")

                    if sumValue not in result:
                        result[sumValue] = Expression(sumValue, sumText, "+")

                    productValue = leftExpression.value * rightExpression.value
                    productText = self._formatExpression(leftExpression, rightExpression, "*")

                    if productValue not in result:
                        result[productValue] = Expression(productValue, productText, "*")

        memo[key] = result
        return result

    def _formatExpression(
        self,
        leftExpression: Expression,
        rightExpression: Expression,
        operator: str
    ) -> str:
        leftText = leftExpression.text
        rightText = rightExpression.text

        if self._needsParentheses(leftExpression.operator, operator):
            leftText = "(" + leftText + ")"

        if self._needsParentheses(rightExpression.operator, operator):
            rightText = "(" + rightText + ")"

        return leftText + operator + rightText

    def _needsParentheses(self, childOperator: str, parentOperator: str) -> bool:
        if childOperator == "":
            return False

        if childOperator == parentOperator:
            return False

        return parentOperator == "*" and childOperator == "+"

