def solution(numbers, target):
    n = len(numbers)
    # For interval [i, j), produce dict: value -> (expr_string, is_sum_at_top)
    # is_sum_at_top marks expressions whose outermost operator is '+', so a
    # parent multiplication knows to wrap them in parentheses.
    from functools import lru_cache

    memo = {}

    def build(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        result = {}
        if j - i == 1:
            result[numbers[i]] = (str(numbers[i]), False)
            memo[(i, j)] = result
            return result
        for k in range(i + 1, j):
            left = build(i, k)
            right = build(k, j)
            for lv, (lexpr, lsum) in left.items():
                for rv, (rexpr, rsum) in right.items():
                    # Addition: no parentheses needed for associativity.
                    add_val = lv + rv
                    if add_val not in result:
                        result[add_val] = (lexpr + "+" + rexpr, True)
                    # Multiplication: wrap any sum-topped operand.
                    lpart = "(" + lexpr + ")" if lsum else lexpr
                    rpart = "(" + rexpr + ")" if rsum else rexpr
                    mul_val = lv * rv
                    if mul_val not in result:
                        result[mul_val] = (lpart + "*" + rpart, False)
        memo[(i, j)] = result
        return result

    if n == 0:
        return ""
    table = build(0, n)
    if target in table:
        return table[target][0] + "=" + str(target)
    return ""

