function solution(numbers, target) {
  const n = numbers.length;
  if (n === 0) return "";
  const memo = new Map();

  function build(i, j) {
    const key = i * 10000 + j;
    if (memo.has(key)) return memo.get(key);
    const result = new Map();
    if (j - i === 1) {
      result.set(numbers[i], { expr: String(numbers[i]), isSum: false });
      memo.set(key, result);
      return result;
    }
    for (let k = i + 1; k < j; k++) {
      const left = build(i, k);
      const right = build(k, j);
      for (const [lv, lo] of left) {
        for (const [rv, ro] of right) {
          const addVal = lv + rv;
          if (!result.has(addVal)) {
            result.set(addVal, { expr: lo.expr + "+" + ro.expr, isSum: true });
          }
          const lpart = lo.isSum ? "(" + lo.expr + ")" : lo.expr;
          const rpart = ro.isSum ? "(" + ro.expr + ")" : ro.expr;
          const mulVal = lv * rv;
          if (!result.has(mulVal)) {
            result.set(mulVal, { expr: lpart + "*" + rpart, isSum: false });
          }
        }
      }
    }
    memo.set(key, result);
    return result;
  }

  const table = build(0, n);
  if (table.has(target)) {
    return table.get(target).expr + "=" + String(target);
  }
  return "";
}

