class StructLayoutManager:
    def __init__(self, fieldNames: List[str], fieldSizes: List[int]):
        self.fields = fieldNames.copy()
        self.offsets = {}
        self.totalSize = 0

        self._initializeOffsets(fieldNames, fieldSizes)

    def _initializeOffsets(self, fieldNames: List[str], fieldSizes: List[int]) -> None:
        for i in range(len(fieldNames)):
            fieldName = fieldNames[i]
            fieldSize = fieldSizes[i]

            self.offsets[fieldName] = self.totalSize
            self.totalSize += fieldSize

    def getOffset(self, fieldName: str) -> int:
        return self.offsets[fieldName]

    def insertField(self, fieldName: str, size: int, index: int) -> None:
        if index < len(self.fields):
            newOffset = self.offsets[self.fields[index]]
        else:
            newOffset = self.totalSize

        for i in range(index, len(self.fields)):
            existingField = self.fields[i]
            self.offsets[existingField] += size

        self.fields.insert(index, fieldName)
        self.offsets[fieldName] = newOffset
        self.totalSize += size

