        return {k: v for k, v in counter.items() if v > 0}

    def near_match(a, b):
        ca, cb = Counter(a), Counter(b)
        choices_a = list(ca.keys()) + [None]
        choices_b = list(cb.keys()) + [None]
        for drop_a in choices_a:
            for drop_b in choices_b:
                na = dict(ca)
                nb = dict(cb)
                if drop_a is not None:
                    na[drop_a] = 0
                if drop_b is not None:
                    nb[drop_b] = 0
                if clean(na) == clean(nb):
                    return True
        return False

    return [near_match(pair[0], pair[1]) for pair in lists]

