function solution(lists) {
  function counter(s) {
    const m = {};
    for (const ch of s) m[ch] = (m[ch] || 0) + 1;
    return m;
  }
  function clean(m) {
    const r = {};
    for (const k in m) if (m[k] > 0) r[k] = m[k];
    return r;
  }
  function eq(a, b) {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    for (const k of ka) if (a[k] !== b[k]) return false;
    return true;
  }
  function nearMatch(a, b) {
    const ca = counter(a);
    const cb = counter(b);
    const choicesA = Object.keys(ca).concat([null]);
    const choicesB = Object.keys(cb).concat([null]);
    for (const dropA of choicesA) {
      for (const dropB of choicesB) {
        const na = Object.assign({}, ca);
        const nb = Object.assign({}, cb);
        if (dropA !== null) na[dropA] = 0;
        if (dropB !== null) nb[dropB] = 0;
        if (eq(clean(na), clean(nb))) return true;
      }
    }
    return false;
  }
  return lists.map(pair => nearMatch(pair[0], pair[1]));
}

