from collections import deque

class CanvasDocument:
    def __init__(self):
        self.objects = {}
        self.undoStack = deque()

    def applyProperty(self, objectId: int, propertyName: str, value: str) -> None:
        if objectId not in self.objects:
            self.objects[objectId] = {}

        obj = self.objects[objectId]

        previousValue = obj.get(propertyName)
        self.undoStack.append([objectId, propertyName, previousValue])

        obj[propertyName] = value

    def getObject(self, objectId: int) -> List[str]:
        if objectId not in self.objects:
            return []

        obj = self.objects[objectId]

        result = []
        for propertyName in sorted(obj.keys()):
            result.append(propertyName + "=" + obj[propertyName])

        return result

    def undo(self) -> None:
        record = self.undoStack.pop()

        objectId = record[0]
        propertyName = record[1]
        previousValue = record[2]

        if previousValue is None:
            del self.objects[objectId][propertyName]
        else:
            self.objects[objectId][propertyName] = previousValue

