function solution(operations, arguments) {
  const results = [];
  const objects = new Map();   // objectId -> Map(name -> value)
  const history = [];          // [objectId, name, previousValueOrNull]
  for (let i = 0; i < operations.length; i++) {
    const op = operations[i];
    const arg = arguments[i];
    if (op === "CanvasDocument") {
      results.push(null);
    } else if (op === "applyProperty") {
      const [oid, name, value] = arg;
      if (!objects.has(oid)) objects.set(oid, new Map());
      const obj = objects.get(oid);
      const old = obj.has(name) ? obj.get(name) : null;
      history.push([oid, name, old]);
      obj.set(name, value);
      results.push(null);
    } else if (op === "getObject") {
      const oid = arg[0];
      const obj = objects.get(oid);
      if (!obj || obj.size === 0) {
        results.push([]);
      } else {
        const keys = Array.from(obj.keys()).sort();
        results.push(keys.map(k => `${k}=${obj.get(k)}`));
      }
    } else if (op === "undo") {
      const [oid, name, old] = history.pop();
      const obj = objects.get(oid);
      if (old === null) obj.delete(name);
      else obj.set(name, old);
      results.push(null);
    }
  }
  return results;
}

