import heapq

class ExchangeEngine:
    def __init__(self, buyerPrices: List[int], sellerPrices: List[int]):
        self.buyHeap = []   # max heap
        self.sellHeap = []  # min heap

        for p in buyerPrices:
            heapq.heappush(self.buyHeap, -p)

        for p in sellerPrices:
            heapq.heappush(self.sellHeap, p)

    def submit(self, price: int, side: str) -> float:
        if side == "seller":
            heapq.heappush(self.sellHeap, price)
        elif side == "buyer":
            heapq.heappush(self.buyHeap, -price)

        if len(self.buyHeap) > 0 and len(self.sellHeap) > 0:
            if -self.buyHeap[0] >= self.sellHeap[0]:
                sellPrice = heapq.heappop(self.sellHeap)
                buyPrice = -heapq.heappop(self.buyHeap)
                return (sellPrice + buyPrice) / 2.0

        return -1.0

