    const a = this.a;
    const top = a[0];
    const last = a.pop();
    if (a.length) {
      a[0] = last;
      let i = 0;
      const n = a.length;
      while (true) {
        let l = 2 * i + 1, r = 2 * i + 2, s = i;
        if (l < n && this.cmp(a[l], a[s]) < 0) s = l;
        if (r < n && this.cmp(a[r], a[s]) < 0) s = r;
        if (s !== i) { [a[i], a[s]] = [a[s], a[i]]; i = s; }
        else break;
      }
    }
    return top;
  }
}

function solution(operations, inputs) {
  const results = [];
  let buyers, sellers;

  function tryMatch() {
    if (buyers.size() && sellers.size() && buyers.peek() >= sellers.peek()) {
      const bid = buyers.pop();
      const ask = sellers.pop();
      return (bid + ask) / 2;
    }
    return null;
  }

  for (let k = 0; k < operations.length; k++) {
    const op = operations[k];
    const arg = inputs[k];
    if (op === "OrderBook") {
      buyers = new MinHeap((x, y) => y - x);
      sellers = new MinHeap((x, y) => x - y);
      for (const p of arg[0]) buyers.push(p);
      for (const p of arg[1]) sellers.push(p);
      results.push(null);
    } else if (op === "submit") {
      const [price, side] = arg;
      if (side === "bid") buyers.push(price);
      else sellers.push(price);
      const matched = tryMatch();
      results.push(matched === null ? -1.0 : matched);
    }
  }
  return results;
}

