from typing import List

class ShipmentTracker:
    def __init__(self):
        self.totalUnits = {}
        self.sentUnits = {}

    def consumeEvents(self, events: List[str]) -> None:
        for event in events:
            self._processEvent(event)

    def _processEvent(self, event: str) -> None:
        parts = event.split(",")
        shipmentId = parts[0].strip()
        units = int(parts[3].strip())
        eventKind = parts[4].strip()

        if eventKind == "CREATED":
            self.totalUnits[shipmentId] = units
            self.sentUnits[shipmentId] = 0
        elif eventKind == "DISPATCHED":
            currentSent = self.sentUnits[shipmentId]
            self.sentUnits[shipmentId] = currentSent + units

    def getShipmentState(self, shipmentId: str) -> str:
        total = self.totalUnits[shipmentId]
        sent = self.sentUnits[shipmentId]

        if sent == total:
            return "DONE"
        elif sent > 0:
            return "PARTIAL"
        else:
            return "CREATED"

