from typing import List


class Solution:
    def maxLineCapacity(
        self,
        capacity: List[int],
        upgradeCost: List[int],
        budget: int,
    ) -> int:
        left = 0
        right = self._getUpperLimit(capacity, upgradeCost, budget)
        answer = 0

        while left <= right:
            mid = (left + right) // 2

            if self._canAchieve(mid, capacity, upgradeCost, budget):
                answer = mid
                left = mid + 1
            else:
                right = mid - 1

        return answer

    def _canAchieve(
        self,
        target: int,
        capacity: List[int],
        upgradeCost: List[int],
        budget: int,
    ) -> bool:
        totalSpent = 0

        for base, cost in zip(capacity, upgradeCost):
            if base < target:
                upgradeTimes = (target - 1) // base
                totalSpent += upgradeTimes * cost

                if totalSpent > budget:
                    return False

        return True

    def _getUpperLimit(
        self,
        capacity: List[int],
        upgradeCost: List[int],
        budget: int,
    ) -> int:
        upper = float("inf")

        for base, cost in zip(capacity, upgradeCost):
            maxReachable = base * (1 + budget // cost)
            upper = min(upper, maxReachable)

        return int(upper)

