function solution(capacity, upgradeCost, budget) {
  // capacity[i] is the starting throughput of machine i
  // upgradeCost[i] is the cost of one upgrade on machine i
  // An upgrade applied x times makes machine i's throughput capacity[i] * (1 + x)
  //   and costs x * upgradeCost[i]
  // The line throughput is the minimum machine throughput.
  // Return the largest line throughput reachable without exceeding budget.
}

reference_solution.javascript:
function solution(capacity, upgradeCost, budget) {
  const n = capacity.length;

  function costToReach(target) {
    let total = 0;
    for (let i = 0; i < n; i++) {
      const base = capacity[i];
      // smallest multiplier m >= 1 with base * m >= target
      const multiplier = Math.max(1, Math.ceil(target / base));
      total += (multiplier - 1) * upgradeCost[i];
      if (total > budget) return total;
    }
    return total;
  }

  let lo = Math.min(...capacity);
  const cheapest = Math.min(...upgradeCost);
  const maxExtra = cheapest > 0 ? Math.floor(budget / cheapest) : 0;
  let hi = Math.max(...capacity) * (maxExtra + 2) + Math.max(...capacity);

  let best = lo;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (costToReach(mid) <= budget) {
      best = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return best;
}

