import bisect


class SocialNetwork:
    def __init__(self):
        self.snap_id = 0
        self.history: Dict[Tuple[int, int], List[Tuple[int, bool]]] = defaultdict(list)

    def follow(self, followerId: int, followeeId: int) -> None:
        key = (followerId, followeeId)
        changes = self.history[key]

        if changes and changes[-1][0] == self.snap_id:
            changes[-1] = (self.snap_id, True)
        elif not changes or changes[-1][1] is False:
            changes.append((self.snap_id, True))

    def unfollow(self, followerId: int, followeeId: int) -> None:
        key = (followerId, followeeId)
        changes = self.history[key]

        if changes and changes[-1][0] == self.snap_id:
            changes[-1] = (self.snap_id, False)
        elif changes and changes[-1][1] is True:
            changes.append((self.snap_id, False))

    def createSnapshot(self) -> int:
        curr = self.snap_id
        self.snap_id += 1
        return curr

    def isFollowing(self, followerId: int, followeeId: int, snapId: int) -> bool:
        key = (followerId, followeeId)
        changes = self.history.get(key, [])

        if not changes:
            return False

        idx = bisect.bisect_right(changes, (snapId, float("inf"))) - 1
        return idx >= 0 and changes[idx][1]

