function solution(operations, inputs) {
  const results = [];
  const current = new Set();   // active edges, keyed "follower#followee"
  const snapshots = [];        // snapshots[id] is a Set of edge keys

  const key = (a, b) => a + "#" + b;

  for (let k = 0; k < operations.length; k++) {
    const op = operations[k];
    const arg = inputs[k];
    if (op === "SocialNetwork") {
      results.push(null);
    } else if (op === "follow") {
      current.add(key(arg[0], arg[1]));
      results.push(null);
    } else if (op === "unfollow") {
      current.delete(key(arg[0], arg[1]));
      results.push(null);
    } else if (op === "createSnapshot") {
      snapshots.push(new Set(current));
      results.push(snapshots.length - 1);
    } else if (op === "isFollowing") {
      const [follower, followee, snapId] = arg;
      if (snapId < 0 || snapId >= snapshots.length) {
        results.push(false);
      } else {
        results.push(snapshots[snapId].has(key(follower, followee)));
      }
    }
  }
