function solution(train, queries) {
  const vocab = {};
  for (const [text] of train) {
    for (const tok of text.toLowerCase().split(/\s+/).filter(Boolean)) {
      if (!(tok in vocab)) vocab[tok] = Object.keys(vocab).length;
    }
  }
  const V = Object.keys(vocab).length;

  function vec(text) {
    const v = new Array(V).fill(0);
    for (const tok of text.toLowerCase().split(/\s+/).filter(Boolean)) {
      if (tok in vocab) v[vocab[tok]] += 1;
    }
    return v;
  }

  const sums = {}, counts = {};
  for (const [text, label] of train) {
    const v = vec(text);
    if (!(label in sums)) { sums[label] = new Array(V).fill(0); counts[label] = 0; }
    for (let i = 0; i < V; i++) sums[label][i] += v[i];
    counts[label] += 1;
  }
  const centroids = {};
  for (const label in sums) centroids[label] = sums[label].map(s => s / counts[label]);

  function cosine(a, b) {
    let dot = 0, na = 0, nb = 0;
    for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
    na = Math.sqrt(na); nb = Math.sqrt(nb);
    if (na === 0 || nb === 0) return 0;
    return dot / (na * nb);
  }

  const labelsSorted = Object.keys(centroids).sort();
  const out = [];
  for (const q of queries) {
    const qv = vec(q);
    let bestLabel = null, bestSim = null;
    for (const label of labelsSorted) {
      const sim = cosine(qv, centroids[label]);
      if (bestSim === null || sim > bestSim + 1e-12) { bestSim = sim; bestLabel = label; }
    }
    out.push(bestLabel);
  }
  return out;
}

