function solution(values, k) {
  const n = values.length;
  let total = 0;
  for (const v of values) if (v > 0) total += v;
  const mags = values.map(v => Math.abs(v)).sort((a, b) => a - b);

  // min-heap of [loss, nextIndex]
  const heap = [];
  function push(item) {
    heap.push(item);
    let c = heap.length - 1;
    while (c > 0) {
      const p = (c - 1) >> 1;
      if (heap[p][0] <= heap[c][0]) break;
      [heap[p], heap[c]] = [heap[c], heap[p]];
      c = p;
    }
  }
  function pop() {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let c = 0;
      while (true) {
        let l = 2 * c + 1, r = 2 * c + 2, s = c;
        if (l < heap.length && heap[l][0] < heap[s][0]) s = l;
        if (r < heap.length && heap[r][0] < heap[s][0]) s = r;
        if (s === c) break;
        [heap[s], heap[c]] = [heap[c], heap[s]];
        c = s;
      }
    }
    return top;
  }

  push([0, 0]);
  let result = total;
  for (let step = 0; step < k; step++) {
    const [loss, i] = pop();
    result = total - loss;
    if (i < n) {
      push([loss + mags[i], i + 1]);
      if (i > 0) push([loss + mags[i] - mags[i - 1], i + 1]);
    }
  }
  return result;
}

