  const rows = grid.length, cols = grid[0].length;
  const dist = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
  dist[0][0] = grid[0][0];
  const pq = [[grid[0][0], 0, 0]];
  function push(item) {
    pq.push(item);
    let c = pq.length - 1;
    while (c > 0) {
      const p = (c - 1) >> 1;
      if (pq[p][0] <= pq[c][0]) break;
      [pq[p], pq[c]] = [pq[c], pq[p]];
      c = p;
    }
  }
  function pop() {
    const top = pq[0];
    const last = pq.pop();
    if (pq.length) {
      pq[0] = last;
      let c = 0;
      while (true) {
        let l = 2 * c + 1, r = 2 * c + 2, s = c;
        if (l < pq.length && pq[l][0] < pq[s][0]) s = l;
        if (r < pq.length && pq[r][0] < pq[s][0]) s = r;
        if (s === c) break;
