  }
  const ipInt = toInt(ip);
  for (const [action, block] of rules) {
    const [net, plenStr] = block.split('/');
    const plen = parseInt(plenStr, 10);
    const netInt = toInt(net);
    if (plen === 0) return action;
    const mask = (0xFFFFFFFF << (32 - plen)) >>> 0;
    if (((ipInt & mask) >>> 0) === ((netInt & mask) >>> 0)) return action;
