def solution(boxIds):
    digits = [int(ch) for ch in boxIds]
    n = len(digits)
    suffix_min = [10] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_min[i] = min(digits[i], suffix_min[i + 1])
    kept = []
    moved = []
    for i in range(n):
        d = digits[i]
        if suffix_min[i + 1] < d:
            moved.append(min(d + 1, 9))
        else:
            kept.append(d)
    moved.sort()
    result = []
    ki = mi = 0
    while ki < len(kept) or mi < len(moved):
        ck = kept[ki] if ki < len(kept) else None
        cm = moved[mi] if mi < len(moved) else None
        if cm is None:
            result.append(ck)
            ki += 1
        elif ck is None:
            result.append(cm)
            mi += 1
        elif cm <= ck:
            result.append(cm)
            mi += 1
        else:
            result.append(ck)
            ki += 1
    return ''.join(str(x) for x in result)

