function solution(boxIds) {
  const digits = boxIds.split('').map(Number);
  const n = digits.length;
  const suffixMin = new Array(n + 1).fill(10);
  for (let i = n - 1; i >= 0; i--) suffixMin[i] = Math.min(digits[i], suffixMin[i + 1]);
  const kept = [];
  const moved = [];
  for (let i = 0; i < n; i++) {
    const d = digits[i];
    if (suffixMin[i + 1] < d) moved.push(Math.min(d + 1, 9));
    else kept.push(d);
  }
  moved.sort((a, b) => a - b);
  const result = [];
  let ki = 0, mi = 0;
  while (ki < kept.length || mi < moved.length) {
    const ck = ki < kept.length ? kept[ki] : null;
    const cm = mi < moved.length ? moved[mi] : null;
    if (cm === null) { result.push(ck); ki++; }
    else if (ck === null) { result.push(cm); mi++; }
    else if (cm <= ck) { result.push(cm); mi++; }
    else { result.push(ck); ki++; }
  }
  return result.map(String).join('');
}

