    dim = len(points[0])
    assign = [-1] * len(points)

    def sqdist(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    for _ in range(maxIter):
        new_assign = []
        for p in points:
            best_i = 0
            best_d = sqdist(p, centroids[0])
            for ci in range(1, k):
                d = sqdist(p, centroids[ci])
                if d < best_d:
                    best_d = d
                    best_i = ci
            new_assign.append(best_i)
        if new_assign == assign:
            break
        assign = new_assign
        sums = [[0.0] * dim for _ in range(k)]
        counts = [0] * k
        for idx, ci in enumerate(assign):
            counts[ci] += 1
            for d in range(dim):
                sums[ci][d] += points[idx][d]
        for ci in range(k):
            if counts[ci] > 0:
                centroids[ci] = [sums[ci][d] / counts[ci] for d in range(dim)]
