function solution(points, k, maxIter) {
  let centroids = [];
  for (let i = 0; i < k; i++) centroids.push(points[i].slice());
  const dim = points[0].length;
  let assign = new Array(points.length).fill(-1);

  function sqdist(a, b) {
    let s = 0;
    for (let i = 0; i < a.length; i++) s += (a[i] - b[i]) * (a[i] - b[i]);
    return s;
  }

  for (let iter = 0; iter < maxIter; iter++) {
    const newAssign = [];
    for (const p of points) {
      let bestI = 0, bestD = sqdist(p, centroids[0]);
      for (let ci = 1; ci < k; ci++) {
        const d = sqdist(p, centroids[ci]);
        if (d < bestD) { bestD = d; bestI = ci; }
      }
      newAssign.push(bestI);
    }
    if (newAssign.every((v, i) => v === assign[i])) break;
    assign = newAssign;
    const sums = Array.from({ length: k }, () => new Array(dim).fill(0));
    const counts = new Array(k).fill(0);
    for (let idx = 0; idx < assign.length; idx++) {
      const ci = assign[idx];
      counts[ci] += 1;
      for (let d = 0; d < dim; d++) sums[ci][d] += points[idx][d];
    }
    for (let ci = 0; ci < k; ci++) {
      if (counts[ci] > 0) centroids[ci] = sums[ci].map(s => s / counts[ci]);
    }
  }
  return assign;
}

