function solution(answers, target) {
  const numThings = answers.length;
  const numQ = numThings > 0 ? answers[0].length : 0;
  let candidates = new Set();
  for (let t = 0; t < numThings; t++) candidates.add(t);
  const asked = [];
  const used = new Array(numQ).fill(false);
  while (candidates.size > 1) {
    let bestQ = -1, bestDist = null;
    const half = candidates.size / 2.0;
    for (let q = 0; q < numQ; q++) {
      if (used[q]) continue;
      let trueCount = 0;
      for (const t of candidates) if (answers[t][q]) trueCount++;
      const dist = Math.abs(trueCount - half);
      if (bestDist === null || dist < bestDist - 1e-12) { bestDist = dist; bestQ = q; }
    }
    if (bestQ === -1) break;
    used[bestQ] = true;
    asked.push(bestQ);
    const tval = answers[target][bestQ];
    const next = new Set();
    for (const t of candidates) if (answers[t][bestQ] === tval) next.add(t);
    candidates = next;
  }
  return asked;
}

