  for (const [f, t, amt] of transactions) {
    bal[f] = (bal[f] || 0) - amt;
    bal[t] = (bal[t] || 0) + amt;
  }
  const debts = Object.values(bal).filter(v => v !== 0);
  const n = debts.length;

  function backtrack(start) {
    while (start < n && debts[start] === 0) start++;
    if (start === n) return 0;
