from collections import deque

def solution(n, prerequisites):
    indeg = [0] * n
    adj = [[] for _ in range(n)]
    for a, b in prerequisites:
        adj[a].append(b)
        indeg[b] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    semesters = 0
    taken = 0
    while q:
        semesters += 1
        for _ in range(len(q)):
            node = q.popleft()
            taken += 1
            for nxt in adj[node]:
                indeg[nxt] -= 1
                if indeg[nxt] == 0:
                    q.append(nxt)
    return semesters if taken == n else -1

