function solution(n, prerequisites) {
  const indeg = new Array(n).fill(0);
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of prerequisites) { adj[a].push(b); indeg[b] += 1; }
  let q = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) q.push(i);
  let semesters = 0, taken = 0;
  while (q.length) {
    semesters += 1;
    const next = [];
    for (const node of q) {
      taken += 1;
      for (const nx of adj[node]) {
        indeg[nx] -= 1;
        if (indeg[nx] === 0) next.push(nx);
      }
    }
    q = next;
  }
  return taken === n ? semesters : -1;
}

