  const out = [];
  for (const cmd of commands) {
    const op = cmd[0];
    if (op === "add") {
      const [, tid, pr, ts] = cmd;
      tasks.set(tid, [pr, ts]);
    } else if (op === "get") {
      const tid = cmd[1];
      out.push(tasks.has(tid) ? tasks.get(tid)[0] : -1);
    } else if (op === "remove") {
