function solution(scores) {
  const heap = scores.slice();
  function up(i) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] >= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  }
  function down(i) {
    const n = heap.length;
    while (true) {
      let l = 2 * i + 1, r = 2 * i + 2, big = i;
      if (l < n && heap[l] > heap[big]) big = l;
      if (r < n && heap[r] > heap[big]) big = r;
      if (big === i) break;
