function solution(intervals) {
  if (intervals.length === 0) return 0;
  const meetings = intervals.slice().sort((a, b) => a[0] - b[0]);
  // simple binary min-heap of end times
  const heap = [];
  const push = (v) => {
    heap.push(v);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      const n = heap.length;
      while (true) {
        let l = 2 * i + 1, r = 2 * i + 2, s = i;
        if (l < n && heap[l] < heap[s]) s = l;
        if (r < n && heap[r] < heap[s]) s = r;
        if (s === i) break;
        [heap[s], heap[i]] = [heap[i], heap[s]];
        i = s;
      }
    }
    return top;
  };
  for (const [start, end] of meetings) {
    if (heap.length && heap[0] <= start) {
      pop();
      push(end);
    } else {
      push(end);
    }
  }
  return heap.length;
}

