    const dq = history.get(client);
    let head = 0;
    while (head < dq.length && dq[head] <= ts - window_ms) head++;
    if (head > 0) dq.splice(0, head);
    if (dq.length < limit) {
      dq.push(ts);
      result.push(true);
    } else {
      result.push(false);
    }
  }
  return result;
