      let bestI = 0, bestD = sqdist(p, centroids[0]);
      for (let ci = 1; ci < k; ci++) {
        const d = sqdist(p, centroids[ci]);
        if (d < bestD) { bestD = d; bestI = ci; }
      }
      newAssign.push(bestI);
    }
    if (newAssign.every((v, i) => v === assign[i])) break;
    assign = newAssign;
    const sums = Array.from({ length: k }, () => new Array(dim).fill(0));
    const counts = new Array(k).fill(0);
    for (let idx = 0; idx < assign.length; idx++) {
      const ci = assign[idx];
      counts[ci] += 1;
      for (let d = 0; d < dim; d++) sums[ci][d] += points[idx][d];
