reference_solution.python:
import heapq

def solution(grid):
    n = len(grid)
    if n == 0:
        return 0
    m = len(grid[0])
    visited = [[False] * m for _ in range(n)]
    heap = [(grid[0][0], 0, 0)]
    while heap:
        cost, r, c = heapq.heappop(heap)
        if visited[r][c]:
            continue
        visited[r][c] = True
        if r == n - 1 and c == m - 1:
            return cost
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc]:
                heapq.heappush(heap, (max(cost, grid[nr][nc]), nr, nc))
    return -1

reference_solution.javascript:
function solution(grid) {
  const n = grid.length;
  if (n === 0) return 0;
  const m = grid[0].length;
  const visited = Array.from({length: n}, () => new Array(m).fill(false));
  const heap = [[grid[0][0], 0, 0]];
  const push = (item) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p][0] <= heap[i][0]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0; const len = heap.length;
      while (true) {
        let l = 2*i+1, r = 2*i+2, s = i;
        if (l < len && heap[l][0] < heap[s][0]) s = l;
        if (r < len && heap[r][0] < heap[s][0]) s = r;
        if (s === i) break;
        [heap[s], heap[i]] = [heap[i], heap[s]];
        i = s;
      }
    }
    return top;
  };
  while (heap.length) {
    const [cost, r, c] = pop();
    if (visited[r][c]) continue;
    visited[r][c] = true;
    if (r === n - 1 && c === m - 1) return cost;
    for (const [dr, dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < m && !visited[nr][nc]) {
        push([Math.max(cost, grid[nr][nc]), nr, nc]);
      }
    }
  }
  return -1;
}

