def solution(accounts):
    n = len(accounts)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    # map (attribute, value) -> first account index that used it
    seen = {}
    for i, acc in enumerate(accounts):
        for attr, val in acc.items():
            key = (attr, val)
            if key in seen:
                union(seen[key], i)
            else:
                seen[key] = i

    groups = {}
    for i in range(n):
        root = find(i)
        groups.setdefault(root, []).append(i)

    result = [sorted(members) for members in groups.values() if len(members) > 1]
    result.sort(key=lambda g: g[0])
    return result

reference_solution.javascript:
function solution(accounts) {
  const n = accounts.length;
  const parent = Array.from({length: n}, (_, i) => i);
  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }
  function union(a, b) {
    const ra = find(a), rb = find(b);
    if (ra !== rb) parent[Math.max(ra, rb)] = Math.min(ra, rb);
  }
  const seen = new Map();
  for (let i = 0; i < n; i++) {
    for (const attr of Object.keys(accounts[i])) {
      const key = attr + "\u0000" + accounts[i][attr];
      if (seen.has(key)) union(seen.get(key), i);
      else seen.set(key, i);
    }
  }
  const groups = new Map();
  for (let i = 0; i < n; i++) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(i);
  }
  const result = [];
  for (const members of groups.values()) {
    if (members.length > 1) result.push(members.slice().sort((a, b) => a - b));
  }
  result.sort((a, b) => a[0] - b[0]);
  return result;
}

