reference_solution.python:
def solution(referrals, k):
    children = {}
    people = set()
    for r, e in referrals:
        children.setdefault(r, []).append(e)
        people.add(r)
        people.add(e)

    cache = {}
    def reach(node):
        if node in cache:
            return cache[node]
        total = 0
        for child in children.get(node, []):
            total += 1 + reach(child)
        cache[node] = total
        return total

    scored = [(reach(p), p) for p in people]
    scored.sort(key=lambda x: (-x[0], x[1]))
    return [name for _, name in scored[:k]]

reference_solution.javascript:
function solution(referrals, k) {
  const children = new Map();
  const people = new Set();
  for (const [r, e] of referrals) {
    if (!children.has(r)) children.set(r, []);
    children.get(r).push(e);
    people.add(r);
    people.add(e);
  }
  const cache = new Map();
  function reach(node) {
    if (cache.has(node)) return cache.get(node);
    let total = 0;
    for (const child of (children.get(node) || [])) {
      total += 1 + reach(child);
    }
    cache.set(node, total);
    return total;
  }
  const scored = [...people].map(p => [reach(p), p]);
  scored.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
  return scored.slice(0, k).map(x => x[1]);
}

