function solution(definitions) {
  const WHITE = 0, GRAY = 1, BLACK = 2;
  const color = {};
  for (const sym of Object.keys(definitions)) color[sym] = WHITE;
  const value = {};
  let cycle = false;

  function dfs(sym) {
    if (cycle) return 0;
    color[sym] = GRAY;
    let total = 0;
    for (const term of definitions[sym]) {
      if (typeof term === "string") {
        if (color[term] === GRAY) { cycle = true; return 0; }
        if (color[term] === WHITE) {
          dfs(term);
          if (cycle) return 0;
        }
        total += value[term];
      } else {
        total += term;
      }
    }
    color[sym] = BLACK;
    value[sym] = total;
    return total;
  }

  for (const sym of Object.keys(definitions)) {
    if (color[sym] === WHITE) {
      dfs(sym);
      if (cycle) return "CYCLE";
    }
  }
  return value;
}

