reference_solution.python:
def solution(operations):
    literal = {}      # cell -> int
    formula = {}      # cell -> list of refs
    out = []

    def value(cell, stack):
        if cell in formula:
            total = 0
            for ref in formula[cell]:
                total += value(ref, stack)
            return total
        return literal.get(cell, 0)

    def creates_cycle(target, refs):
        # would defining target=sum(refs) cause target to reach itself?
        seen = set()
        def reaches(cell):
            if cell == target:
                return True
            if cell in seen:
                return False
            seen.add(cell)
            for r in formula.get(cell, []):
                if reaches(r):
                    return True
            return False
        return any(reaches(r) for r in refs)

    for op in operations:
        kind = op[0]
        if kind == "set":
            _, cell, val = op
            literal[cell] = val
            formula.pop(cell, None)
        elif kind == "setFormula":
            _, cell, refs = op
            # temporarily consider cell as a formula over refs for cycle check
            if creates_cycle(cell, refs):
                out.append("CIRCULAR")
            else:
                formula[cell] = list(refs)
                literal.pop(cell, None)
        elif kind == "get":
            cell = op[1]
            out.append(value(cell, set()))
    return out

reference_solution.javascript:
function solution(operations) {
  const literal = new Map();
  const formula = new Map();
  const out = [];

  function value(cell) {
    if (formula.has(cell)) {
      let total = 0;
      for (const ref of formula.get(cell)) total += value(ref);
      return total;
    }
    return literal.has(cell) ? literal.get(cell) : 0;
  }

  function createsCycle(target, refs) {
    const seen = new Set();
    function reaches(cell) {
      if (cell === target) return true;
      if (seen.has(cell)) return false;
      seen.add(cell);
      for (const r of (formula.get(cell) || [])) {
        if (reaches(r)) return true;
      }
      return false;
    }
    return refs.some(r => reaches(r));
  }

  for (const op of operations) {
    const kind = op[0];
    if (kind === "set") {
      literal.set(op[1], op[2]);
      formula.delete(op[1]);
    } else if (kind === "setFormula") {
      const cell = op[1], refs = op[2];
      if (createsCycle(cell, refs)) {
        out.push("CIRCULAR");
      } else {
        formula.set(cell, refs.slice());
        literal.delete(cell);
      }
    } else if (kind === "get") {
      out.push(value(op[1]));
    }
  }
  return out;
}

