reference_solution.python:
from collections import deque

def solution(n, edges, a, b):
    if a == b:
        return 0
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    dist = [-1] * n
    dist[a] = 0
    q = deque([a])
    while q:
        node = q.popleft()
        if node == b:
            return dist[node]
        for nxt in adj[node]:
            if dist[nxt] == -1:
                dist[nxt] = dist[node] + 1
                q.append(nxt)
    return -1

reference_solution.javascript:
function solution(n, edges, a, b) {
  if (a === b) return 0;
  const adj = Array.from({length: n}, () => []);
  for (const [u, v] of edges) {
    adj[u].push(v);
    adj[v].push(u);
  }
  const dist = new Array(n).fill(-1);
  dist[a] = 0;
  const q = [a];
  let head = 0;
  while (head < q.length) {
    const node = q[head++];
    if (node === b) return dist[node];
    for (const nxt of adj[node]) {
      if (dist[nxt] === -1) {
        dist[nxt] = dist[node] + 1;
        q.push(nxt);
      }
    }
  }
  return -1;
}

