function solution(text, phrases) {
  const intervals = [];
  for (const p of phrases) {
    if (!p) continue;
    let start = text.indexOf(p);
    while (start !== -1) {
      intervals.push([start, start + p.length]);
      start = text.indexOf(p, start + 1);
    }
  }
  if (intervals.length === 0) return text;
  intervals.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  let cs = intervals[0][0], ce = intervals[0][1];
  for (let i = 1; i < intervals.length; i++) {
    const [s, e] = intervals[i];
    if (s <= ce) ce = Math.max(ce, e);
    else { merged.push([cs, ce]); cs = s; ce = e; }
  }
  merged.push([cs, ce]);
  let out = "";
  let prev = 0;
  for (const [s, e] of merged) {
    out += text.slice(prev, s);
    out += "<yellow>" + text.slice(s, e) + "</yellow>";
    prev = e;
  }
  out += text.slice(prev);
  return out;
}

