reference_solution.javascript:
function solution(logits, draws) {
  const m = Math.max(...logits);
  const exps = logits.map(x => Math.exp(x - m));
  const total = exps.reduce((a, b) => a + b, 0);
  const probs = exps.map(e => e / total);
  const cdf = [];
  let run = 0;
  for (const p of probs) { run += p; cdf.push(run); }
  const out = [];
  for (const u of draws) {
    let chosen = cdf.length - 1;
    for (let i = 0; i < cdf.length; i++) {
      if (cdf[i] > u) { chosen = i; break; }
    }
    out.push(chosen);
  }
  return out;
}

