reference_solution.python:
def solution(grid):
    n = len(grid)
    board = [list(row) for row in grid]
    col_used = [False] * n

    def adjacent_house_ok(r, c):
        # check that placing F at (r,c) does not give any neighboring house
        # a second adjacent flower
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and board[nr][nc] == 'H':
                # count flowers already adjacent to this house
                cnt = 0
                for dr2, dc2 in ((1,0),(-1,0),(0,1),(0,-1)):
                    hr, hc = nr + dr2, nc + dc2
                    if 0 <= hr < n and 0 <= hc < n and board[hr][hc] == 'F':
                        cnt += 1
                if cnt >= 1:  # already one flower adjacent; this would be a second
                    return False
        return True

    def backtrack(r):
        if r == n:
            return True
        for c in range(n):
            if not col_used[c] and board[r][c] != 'H' and adjacent_house_ok(r, c):
                board[r][c] = 'F'
                col_used[c] = True
                if backtrack(r + 1):
                    return True
                board[r][c] = '.'
                col_used[c] = False
        return False

    if backtrack(0):
        return ["".join(row) for row in board]
    return []

