function solution(grid) {
  const n = grid.length;
  const board = grid.map(row => row.split(''));
  const colUsed = new Array(n).fill(false);

  function adjacentHouseOk(r, c) {
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n && board[nr][nc] === 'H') {
        let cnt = 0;
        for (const [dr2, dc2] of dirs) {
          const hr = nr + dr2, hc = nc + dc2;
          if (hr >= 0 && hr < n && hc >= 0 && hc < n && board[hr][hc] === 'F') cnt++;
        }
        if (cnt >= 1) return false;
      }
    }
    return true;
  }

  function backtrack(r) {
    if (r === n) return true;
    for (let c = 0; c < n; c++) {
      if (!colUsed[c] && board[r][c] !== 'H' && adjacentHouseOk(r, c)) {
        board[r][c] = 'F';
        colUsed[c] = true;
        if (backtrack(r + 1)) return true;
        board[r][c] = '.';
        colUsed[c] = false;
      }
    }
    return false;
  }

  if (backtrack(0)) return board.map(row => row.join(''));
  return [];
}

