reference_solution.python:
def solution(config, operations):
    ban = config.get("ban", "")
    max_len = config.get("max_len", 0)
    stored = []
    out = []

    def process(msg):
        if ban:
            msg = msg.replace(ban, "")
        msg = msg[:max_len]
        if msg:
            msg = msg[0].upper() + msg[1:].lower()
        return msg

    for op in operations:
        kind = op[0]
        if kind == "log":
            stored.append(process(op[1]))
        elif kind == "all":
            out.append(list(stored))
        elif kind == "search":
            term = op[1]
            out.append([m for m in stored if term in m])
    return out

reference_solution.javascript:
function solution(config, operations) {
  const ban = config.ban || "";
  const maxLen = config.max_len || 0;
  const stored = [];
  const out = [];

  function process(msg) {
    if (ban) msg = msg.split(ban).join("");
    msg = msg.slice(0, maxLen);
    if (msg.length > 0) msg = msg[0].toUpperCase() + msg.slice(1).toLowerCase();
    return msg;
  }

  for (const op of operations) {
    const kind = op[0];
    if (kind === "log") {
      stored.push(process(op[1]));
    } else if (kind === "all") {
      out.push(stored.slice());
    } else if (kind === "search") {
      const term = op[1];
      out.push(stored.filter(m => m.includes(term)));
    }
  }
  return out;
}

