def solution(operations):
    # tree node: dict mapping name -> node; files are marked with key '__file__': True
    root = {}
    out = []

    def get_node(parts):
        node = root
        for part in parts:
            if part in node and isinstance(node[part], dict):
                node = node[part]
            else:
                return None
        return node

    for op in operations:
        kind = op[0]
        if kind == "add":
            parts = op[1].split("/")
            *folders, name = parts
            node = root
            for f in folders:
                if f not in node or not isinstance(node[f], dict) or node[f].get("__file__"):
                    node[f] = {}
                node = node[f]
            final = name
            if final in node:
                k = 1
                while f"{name}({k})" in node:
                    k += 1
                final = f"{name}({k})"
            node[final] = {"__file__": True}
            out.append(final)
        elif kind == "get":
            parts = op[1].split("/")
            node = get_node(parts)
            if node is None:
                out.append("none")
            elif node.get("__file__"):
                out.append("file")
            else:
                out.append("folder")
    return out

reference_solution.javascript:
function solution(operations) {
  const root = {};
  const out = [];

  function getNode(parts) {
    let node = root;
    for (const part of parts) {
      if (node[part] && typeof node[part] === "object") node = node[part];
      else return null;
    }
    return node;
  }

  for (const op of operations) {
    const kind = op[0];
    if (kind === "add") {
      const parts = op[1].split("/");
      const name = parts[parts.length - 1];
      const folders = parts.slice(0, -1);
      let node = root;
      for (const f of folders) {
        if (!node[f] || typeof node[f] !== "object" || node[f].__file__) node[f] = {};
        node = node[f];
      }
      let final = name;
      if (final in node) {
        let k = 1;
        while ((name + "(" + k + ")") in node) k++;
        final = name + "(" + k + ")";
      }
      node[final] = { __file__: true };
      out.push(final);
    } else if (kind === "get") {
      const parts = op[1].split("/");
      const node = getNode(parts);
      if (node === null) out.push("none");
      else if (node.__file__) out.push("file");
      else out.push("folder");
    }
  }
  return out;
}

