    arr = sorted(cards)
    n = len(arr)
    best = None
    for i in range(n - 2):
        lo, hi = i + 1, n - 1
        while lo < hi:
            s = arr[i] + arr[lo] + arr[hi]
            if s == 15:
                triple = [arr[i], arr[lo], arr[hi]]
                if best is None or triple < best:
