reference_solution.javascript:
function solution(cards) {
  const arr = cards.slice().sort((a, b) => a - b);
  const n = arr.length;
  let best = null;
  function lex(a, b) {
    for (let i = 0; i < 3; i++) {
      if (a[i] !== b[i]) return a[i] - b[i];
    }
    return 0;
  }
  for (let i = 0; i < n - 2; i++) {
    let lo = i + 1, hi = n - 1;
    while (lo < hi) {
      const s = arr[i] + arr[lo] + arr[hi];
      if (s === 15) {
        const triple = [arr[i], arr[lo], arr[hi]];
        if (best === null || lex(triple, best) < 0) best = triple;
        lo++;
        hi--;
      } else if (s < 15) {
        lo++;
      } else {
        hi--;
      }
    }
  }
  return best === null ? [] : best;
}

