reference_solution.python:
def solution(ops):
    from collections import deque
    limit = 0
    window = 0
    log = deque()
    out = []
    for op in ops:
        if op[0] == 'init':
            limit, window = op[1], op[2]
            log.clear()
        elif op[0] == 'allow':
            ts = op[1]
            while log and log[0] <= ts - window:
                log.popleft()
            if len(log) < limit:
                log.append(ts)
                out.append(True)
            else:
                out.append(False)
    return out

reference_solution.javascript:
function solution(ops) {
  let limit = 0, window = 0;
  const log = [];
  let head = 0;
  const out = [];
  for (const op of ops) {
    if (op[0] === 'init') {
      limit = op[1]; window = op[2];
      log.length = 0; head = 0;
    } else if (op[0] === 'allow') {
      const ts = op[1];
      while (head < log.length && log[head] <= ts - window) head++;
      if (log.length - head < limit) {
        log.push(ts);
        out.push(true);
      } else {
        out.push(false);
      }
    }
  }
  return out;
}

