function solution(ops) {
  const store = {};
  const putTimes = [];
  const getTimes = [];
  const out = [];
  for (const op of ops) {
    const kind = op[0];
    if (kind === "put") {
      const [, ts, key, value] = op;
      store[key] = value;
      putTimes.push(ts);
    } else if (kind === "get") {
      const [, ts, key] = op;
      const _ = store[key];
      getTimes.push(ts);
    } else if (kind === "rate") {
      const [, ts, target, window] = op;
      const times = target === "put" ? putTimes : getTimes;
      const lo = ts - window;
      let count = 0;
      for (const t of times) if (t > lo && t <= ts) count += 1;
      out.push((count / window).toFixed(4));
