      if (size === 0) out.push(-1);
      else {
        const val = buf[head];
        head = (head + 1) % cap;
        size--;
        out.push(val);
      }
    } else if (name === 'isEmpty') {
      out.push(size === 0);
    } else if (name === 'isFull') {
      out.push(size === cap);
    }
  }
