function solution(points) {
  const arr = [...points];
  const n = arr.length;
  const target = Math.floor((n - 1) / 2);
  function quickselect(lo, hi, kth) {
    while (lo < hi) {
      const pivot = arr[Math.floor((lo + hi) / 2)];
      let i = lo, j = hi;
      while (i <= j) {
        while (arr[i] < pivot) i++;
        while (arr[j] > pivot) j--;
        if (i <= j) {
          [arr[i], arr[j]] = [arr[j], arr[i]];
          i++; j--;
        }
      }
      if (kth <= j) hi = j;
      else if (kth >= i) lo = i;
      else return arr[kth];
    }
    return arr[kth];
  }
  return quickselect(0, n - 1, target);
}

