function solution(text, keywords) {
  const n = text.length;
  const bold = new Array(n).fill(false);
  for (const kw of keywords) {
    if (!kw) continue;
    let start = text.indexOf(kw);
    while (start !== -1) {
      for (let i = start; i < start + kw.length; i++) bold[i] = true;
      start = text.indexOf(kw, start + 1);
    }
  }
  let result = '';
  let i = 0;
  while (i < n) {
    if (bold[i]) {
      result += '<b>';
      while (i < n && bold[i]) { result += text[i]; i++; }
      result += '</b>';
    } else {
      result += text[i];
      i++;
    }
  }
  return result;
}

