function solution(p) {
  const n = p.length;
  const pos = new Array(n + 1).fill(0);
  for (let idx = 0; idx < n; idx++) pos[p[idx]] = idx;
  const out = [];
  let lo = Infinity, hi = -Infinity;
  for (let k = 1; k <= n; k++) {
    lo = Math.min(lo, pos[k]);
    hi = Math.max(hi, pos[k]);
    out.push(hi - lo + 1 === k);
  }
  return out;
}

