function solution(nums1, nums2, k) {
  if (nums1.length === 0 || nums2.length === 0 || k <= 0) return [];
  const heap = [];
  const cmp = (x, y) => {
    if (x[0] !== y[0]) return x[0] - y[0];
    if (x[1] !== y[1]) return x[1] - y[1];
    return x[2] - y[2];
  };
  const up = (n) => {
    while (n > 0) {
      const p = (n - 1) >> 1;
      if (cmp(heap[n], heap[p]) < 0) { [heap[n], heap[p]] = [heap[p], heap[n]]; n = p; }
      else break;
    }
  };
  const down = (n) => {
    const len = heap.length;
    while (true) {
      let s = n, l = 2 * n + 1, r = 2 * n + 2;
      if (l < len && cmp(heap[l], heap[s]) < 0) s = l;
      if (r < len && cmp(heap[r], heap[s]) < 0) s = r;
      if (s === n) break;
      [heap[n], heap[s]] = [heap[s], heap[n]]; n = s;
    }
  };
  const push = (v) => { heap.push(v); up(heap.length - 1); };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) { heap[0] = last; down(0); }
    return top;
  };
  const lim = Math.min(k, nums1.length);
  for (let i = 0; i < lim; i++) push([nums1[i] + nums2[0], nums1[i], nums2[0], i, 0]);
  const out = [];
  while (heap.length && out.length < k) {
    const [s, a, b, i, j] = pop();
    out.push([a, b]);
    if (j + 1 < nums2.length) {
      const nj = j + 1;
      push([nums1[i] + nums2[nj], nums1[i], nums2[nj], i, nj]);
    }
  }
  return out;
}

