function solution(commands) {
  const arr = [];
  const pos = new Map();
  const out = [];
  for (const cmd of commands) {
    const op = cmd[0];
    if (op === "insert") {
      const val = cmd[1];
      if (pos.has(val)) {
        out.push(false);
      } else {
        pos.set(val, arr.length);
        arr.push(val);
        out.push(true);
      }
    } else if (op === "remove") {
      const val = cmd[1];
      if (!pos.has(val)) {
        out.push(false);
      } else {
        const i = pos.get(val);
        const last = arr[arr.length - 1];
        arr[i] = last;
        pos.set(last, i);
        arr.pop();
        pos.delete(val);
        out.push(true);
      }
    } else if (op === "snapshot") {
      out.push(arr.slice());
    }
  }
  return out;
}
